INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('1eb94624-339d-4264-8f6f-b864619f57c6', NULL, NULL, NULL, '{"summary": "A Seara enfrenta o desafio de embutidos em um mercado cauteloso. Deve inovar em Clean Label e Plant-Based, usando sua força de distribuição para se adaptar e crescer.", "threats": [{"source": "análise de mercado", "content": "Mudança de hábito do consumidor para flexitarianismo e ''Clean Label''.", "confidence": "Alta"}, {"source": "fato", "content": "Reforma Tributária e novas regras de rotulagem (RDC 429/2020).", "confidence": "Alta"}, {"source": "fato", "content": "Cenário de juros altos e consumidor cauteloso, impactando poder de compra.", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Alta rivalidade e ameaça de substitutos (marcas próprias, pequenos produtores).", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Forte capacidade de distribuição e logística nacional (Grupo JBS).", "confidence": "Alta"}, {"source": "fato", "content": "Portfólio diversificado em congelados, resfriados e plant-based.", "confidence": "Alta"}, {"source": "fato", "content": "Investimento robusto em marketing e P&D (Linha Incrível, Seara Gourmet).", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Liderança de mercado em categorias-chave, alta penetração nos lares.", "confidence": "Média"}], "weaknesses": [{"source": "análise de mercado", "content": "Percepção negativa de ultraprocessados e impacto na saúde (embutidos).", "confidence": "Alta"}, {"source": "fato", "content": "Dependência de commodities (milho/soja) expõe a volatilidade de custos.", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Sensibilidade de preço do consumidor em cenário inflacionário.", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Desafio de adaptar linhas tradicionais às novas regras de rotulagem.", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Inovação em produtos ''Clean Label'' e com menos aditivos.", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Expansão da linha Plant-Based para atender flexitarianos.", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Desenvolvimento de produtos práticos e saudáveis (Ready-to-eat).", "confidence": "Média"}, {"source": "análise de mercado", "content": "Otimização operacional via tecnologia para reduzir custos e preços.", "confidence": "Média"}]}'::jsonb, '{"legal": ["RDC 429/2020 (Rotulagem Nutricional Frontal) exige adaptação.", "Regulamentação específica para Plant-Based (nomenclatura) em breve.", "SIF, ISO 22000, HACCP são requisitos contínuos de conformidade."], "social": ["Ascensão do flexitarianismo e redução de carne impactam embutidos.", "Busca por ''Clean Label'' e menos aditivos desafia produtos atuais.", "Consumidor cauteloso busca custo-benefício ou valor agregado claro."], "summary": "A Seara enfrenta um cenário de juros altos e consumidor cauteloso, com a Reforma Tributária e novas regras de rotulagem (RDC 429/2020) exigindo adaptação. A mudança de hábitos para flexitarianismo e ''Clean Label'' desafia o modelo de embutidos, enquanto a inovação em Plant-Based e ESG são cruciais para o futuro.", "economic": ["Juros altos (SELIC 14.90%) pressionam consumo e encarecem crédito.", "Inflação (IPCA 0.09% ac. 12m) afeta poder de compra do consumidor.", "IPP em queda (-0.25%) favorece margens, custo ração estabiliza."], "political": ["Reforma Tributária impacta cesta básica e preços ao consumidor.", "Estabilidade política moderada exige atenção ao cenário fiscal.", "Normas de bem-estar animal para exportação (UE) influenciam produção."], "environmental": ["Protocolos ESG de rastreabilidade de grãos e gado são exigidos.", "Endurecimento de metas de descarbonização na cadeia de valor.", "Críticas sobre ultraprocessados impulsionam busca por naturalidade."], "technological": ["Indústria 4.0 e rastreabilidade Blockchain aumentam eficiência.", "Tecnologias para redução de sódio/gorduras são cruciais para reformulação.", "Inovação em Plant-Based (Fazenda Futuro) é ameaça e oportunidade."]}'::jsonb, '{"summary": "A Seara opera em um mercado de alta rivalidade e poder de compra do consumidor, com forte ameaça de substitutos devido à mudança de hábitos. As barreiras de entrada são altas. A empresa deve focar em inovação (clean label, plant-based), eficiência operacional via tecnologia e parcerias estratégicas para manter sua posição e crescer em um cenário desafiador.", "buyer_power": "O poder de barganha dos compradores é alto. O consumidor está cauteloso, buscando custo-benefício ou valor agregado claro, e a inflação (IPCA 0.09%) e juros altos (SELIC 14.90%) pressionam o consumo, incentivando trade-down para marcas próprias.", "supplier_power": "O poder dos fornecedores é médio. Embora o IPP em queda (-0.25%) favoreça margens e o custo de ração estabilize, a Seara ainda depende de commodities agrícolas, mas sua escala e volume de compra (JBS) mitigam parte desse poder.", "disruption_ai_data": "A disrupção por IA/Dados é média. A tecnologia de Indústria 4.0 e rastreabilidade blockchain já é adotada. IA pode otimizar supply chain e P&D, mas a ameaça de disrupção radical no core business de alimentos processados é gradual, não imediata.", "threat_substitutes": "A ameaça de substitutos é alta. A mudança de hábito (''Ninguém come embutido''), ascensão do flexitarianismo e marcas próprias de supermercados ganhando espaço (trade down) são ameaças diretas aos produtos tradicionais da Seara.", "competitive_rivalry": "A rivalidade é alta devido ao duopólio JBS/Seara e BRF, com concorrentes reformulando produtos para evitar selos ''Alto em Sódio'' e expandindo linhas de empanados, exigindo diferenciação constante e investimento em P&D para manter a liderança de mercado. A concentração é alta.", "threat_new_entrants": "A ameaça de novos entrantes é baixa. As barreiras são altas devido à escala logística, regulamentação (SIF/Exportação) e capital intensivo. O setor tem alta concentração de mercado, dificultando a entrada de novos players relevantes.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Investir em P&D para desenvolver produtos ''Clean Label'', com menos sódio/gordura e opções plant-based, alinhados à RDC 429/2020 e tendências de flexitarianismo.", "Fortalecer a proposta de valor em linhas gourmet e pratos prontos, oferecendo conveniência e diferenciação para justificar preços em um cenário de consumidor cauteloso.", "Otimizar a cadeia de suprimentos e produção com Indústria 4.0 e IA para ganhos de eficiência, mitigando volatilidade de custos e pressões de margem.", "Explorar parcerias estratégicas com empresas de tecnologia alimentar ou startups para acelerar a inovação em novos nichos e plataformas de consumo."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Média", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "O poder de parcerias e ecossistemas é médio. Tendências como Clean Label e Plant-based exigem colaborações para inovação. A Seara pode buscar alianças com startups de tecnologia alimentar ou fornecedores de ingredientes sustentáveis para atender novas demandas.", "threat_new_entrants_intensity": "Baixa", "power_partnerships_ecosystems_intensity": "Média"}'::jsonb, '{"summary": "Plano de 90 dias focado em estruturar P&D, legal e marketing para Seara Saudável e Embutidos do Bem, com prospecção de parcerias para inovação.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar as bases para o lançamento da linha ''Seara Saudável'' e a reformulação de embutidos, garantindo alinhamento legal e de P&D.", "investment": "R$ 500 mil - R$ 1 milhão", "key_results": ["Completar a formação da equipe multifuncional (P&D, Marketing, Jurídico) para ''Seara Saudável''.", "Finalizar estudo de viabilidade regulatória e legal para claims de ''